void HUMPlanner::writeArmLimits(ofstream &stream, std::vector<double> &minArmLimits, std::vector<double> &maxArmLimits,bool final, int hand_code)
{
    std::size_t n_joints = minArmLimits.size();

    stream << string("# JOINT LIMITS \n");
    stream << string("# Lower Bounds \n");
    stream << string("param llim {i in 1..")+to_string(n_joints)+string("} ; \n");

    double joint_spacer;
    if(final)
    {
        joint_spacer = SPACER;
    }else{
        joint_spacer = SPACER_BOUNCE;
    }

    for (std::size_t i=0; i < n_joints; ++i){
        string minLim;
        if(!final && (((i == (n_joints-1)) || (i == (n_joints-2))) && hand_code == 3))
            minLim=  boost::str(boost::format("%.8f") % (minArmLimits.at(i)));
        else
            minLim=  boost::str(boost::format("%.8f") % (minArmLimits.at(i)+joint_spacer));
        boost::replace_all(minLim,",",".");
        stream << string("let llim[")+to_string(i+1)+string("] := ")+minLim+string(";\n");
    }

    stream << string("# Upper Bounds \n");
    stream << string("param ulim {i in 1..")+to_string(n_joints)+string("} ; \n");

    for (std::size_t i=0; i < n_joints; ++i){
        string maxLim;
        if(!final && (((i == (n_joints-1)) || (i == (n_joints-2))) && hand_code == 3))
            maxLim=  boost::str(boost::format("%.8f") % (maxArmLimits.at(i)));
        else
            maxLim=  boost::str(boost::format("%.8f") % (maxArmLimits.at(i)-joint_spacer));
        boost::replace_all(maxLim,",",".");
        stream << string("let ulim[")+to_string(i+1)+string("] := ")+maxLim+string(";\n");
    }

}

void HUMPlanner::writeArmLimitsMultipliers(std::ofstream& stream, std::vector<double>& minArmLimitsMultitpliers, std::vector<double>& maxArmLimitsMultipliers,bool final)
{
    std::size_t n_joints = minArmLimitsMultitpliers.size();

    stream << string("# BOUNDS LAGRANGE MULTIPLIERS \n");
    stream << string("# Lower Bounds Multipliers \n");
    stream << string("param zL_in {i in 1..")+to_string(n_joints)+string("} ; \n");

    for (std::size_t i=0; i < n_joints; ++i){
        string zL_str =  boost::str(boost::format("%.8f") % (minArmLimitsMultitpliers.at(i)));
        boost::replace_all(zL_str,",",".");
        stream << string("let zL_in[")+to_string(i+1)+string("] := ")+zL_str+string(";\n");
    }
    stream << string("suffix ipopt_zL_in, IN; \n");
    if(final){
        stream << string("let {i in 1..")+to_string(n_joints)+string("} theta[i].ipopt_zL_in := zL_in[i]; \n");
    }else{
        stream << string("let {i in 1..")+to_string(n_joints)+string("} theta_b[i].ipopt_zL_in := zL_in[i]; \n");
    }

    stream << string("# Upper Bounds Multipliers \n");
    stream << string("param zU_in {i in 1..")+to_string(n_joints)+string("} ; \n");
    for (std::size_t i=0; i < n_joints; ++i){
        string zU_str =  boost::str(boost::format("%.8f") % (maxArmLimitsMultipliers.at(i)));
        boost::replace_all(zU_str,",",".");
        stream << string("let zU_in[")+to_string(i+1)+string("] := ")+zU_str+string(";\n");
    }
    stream << string("suffix ipopt_zU_in, IN; \n");
    if(final){
        stream << string("let {i in 1..")+to_string(n_joints)+string("} theta[i].ipopt_zU_in := zU_in[i]; \n");
    }else{
        stream << string("let {i in 1..")+to_string(n_joints)+string("} theta_b[i].ipopt_zU_in := zU_in[i]; \n");
    }

}

void HUMPlanner::writeConstraintsMultipliersMod(std::ofstream& stream)
{
    stream << string("# CONSTRAINTS LAGRANGE MULTIPLIERS \n");
    stream << string("param n_constr; \n");
    stream << string("param dual_in {i in 1..n_constr}; \n");
}

bool HUMPlanner::writeFinalConstraintsMultipliers(std::ofstream& stream,bool coll, bool coll_body, bool coll_obsts, int n_s, int n_obsts,int mov_type,int pre_post,int n_obj_tar,std::vector<double> &duals)
{
    stream << string("# CONSTRAINTS LAGRANGE MULTIPLIERS \n");
    std::size_t n_constr = 2; // target position and target orientation
    if(coll && coll_obsts){
        n_constr += (15+n_s)*n_obsts; // (15+n_s)X n_obstacles constraints
        if(mov_type==1 && pre_post==2){
            n_constr += (15+n_s)*n_obj_tar; // (15+n_s)X n_obj_tar constraints
        }
    }

    if(coll && coll_body){n_constr += 3;} // 3 constraints with the body

    if(n_constr==duals.size()){
        stream << string("param n_constr := ")+to_string(n_constr)+string("; \n");
        stream << string("param dual_in := \n");
        string dual_str;
        for (std::size_t i=0; i < n_constr; ++i){
            dual_str =  boost::str(boost::format("%.8f") % (duals.at(i))); boost::replace_all(dual_str,",",".");
            if(i==(n_constr-1)){
                stream << to_string(i+1)+string(" ")+dual_str+string("; \n");
            }else{
                stream << to_string(i+1)+string(" ")+dual_str+string("\n");
            }
        }
        return true;
    }else{
        return false;
    }


}

bool HUMPlanner::writeBounceConstraintsMultipliers(std::ofstream& stream, int n_steps, int n_joints, int n_s, int n_obsts,int mov_type,int pre_post,bool coll_tar,bool coll_obsts,std::vector<double> &duals)
{
    stream << string("# CONSTRAINTS LAGRANGE MULTIPLIERS \n");
    std::size_t n_constr = (n_steps+1)*n_joints; // joint trajectory limits constraints
    if(mov_type==0 && pre_post==1)
    {// pick movement in approach stage
        int n_steps_init;
        if(N_STEP_MIN>2){
            n_steps_init = N_STEP_MIN-2;
        }else{
            n_steps_init = 1;
        }
        n_constr += (n_steps+1)-(n_steps-n_steps_init) + 1; // hand rotation constraints
    }
    if(mov_type==0 && coll_tar)
    { // target avoidance during pick movements
        int diff_steps = (int) (n_steps*BLANK_PERCENTAGE_TAR);
        n_constr += 12 *(n_steps-diff_steps); // target avoidance constraints
    }
    if(coll_obsts)
    {// obstacle avoidance
        switch(mov_type)
        {
        case 0:// pick
            n_constr += 15*n_obsts*(n_steps+1);
            break;
        case 1: // place
            n_constr += (15+n_s)*n_obsts*(n_steps+1);
            break;
        case 2: //move
            int diff_steps = std::max(1,(int)(n_steps*BLANK_PERCENTAGE_OBS));
            n_constr += 15*n_obsts*(n_steps+1-diff_steps+1);
            break;
        }

    }
    n_constr += 3*(n_steps+1); //  constraints with the body

    if(n_constr==duals.size()){
        stream << string("param n_constr := ")+to_string(n_constr)+string("; \n");
        stream << string("param dual_in := \n");
        string dual_str;
        for (std::size_t i=0; i < n_constr; ++i){
            dual_str =  boost::str(boost::format("%.8f") % (duals.at(i))); boost::replace_all(dual_str,",",".");
            if(i==(n_constr-1)){
                stream << to_string(i+1)+string(" ")+dual_str+string("; \n");
            }else{
                stream << to_string(i+1)+string(" ")+dual_str+string("\n");
            }
        }
        return true;
    }else{
        return false;
    }

}

void HUMPlanner::writeDualArmLimits(std::ofstream& stream, std::vector<double>& minRightArmLimits,std::vector<double>& maxRightArmLimits,
                        std::vector<double>& minLeftArmLimits,std::vector<double>& maxLeftArmLimits,bool final, int hand_code_right, int hand_code_left)
{

    std::vector<double> minArmLimits; std::vector<double> maxArmLimits;
    minArmLimits = minRightArmLimits;
    minArmLimits.insert(minArmLimits.end(),minLeftArmLimits.begin(),minLeftArmLimits.end());
    maxArmLimits = maxRightArmLimits;
    maxArmLimits.insert(maxArmLimits.end(),maxLeftArmLimits.begin(),maxLeftArmLimits.end());


    stream << string("# JOINT LIMITS \n");
    stream << string("# Lower Bound \n");
    stream << string("param llim := \n");

    double joint_spacer;
    if(final){
        joint_spacer = SPACER;
    }else{
        joint_spacer = SPACER_BOUNCE;
    }

    for (std::size_t i=0; i < minArmLimits.size(); ++i){
        string minLim;
        if(HANDS){
            if(!final && (hand_code_right == 3 && ((i == joints_arm) || i == joints_arm +1)))
                minLim=  boost::str(boost::format("%.8f") % (minArmLimits.at(i)));
            else if(!final && (hand_code_left == 3 && ((i == ((joints_arm * 2) + joints_hand_right)) || (i == ((joints_arm * 2) + joints_hand_right + 1)))))
                minLim=  boost::str(boost::format("%.8f") % (minArmLimits.at(i)));
            else
                minLim=  boost::str(boost::format("%.8f") % (minArmLimits.at(i)+joint_spacer));
        }
        else{
            if(!final && hand_code_right == 3 && hand_code_left == 3 &&
                    ((i = (joints_arm)) || (i = (joints_arm + 1)) || (i == ((joints_arm * 2) + joints_hand)) || (i == ((joints_arm * 2) + joints_hand + 1))))
                minLim=  boost::str(boost::format("%.8f") % (minArmLimits.at(i)));
            else
                minLim=  boost::str(boost::format("%.8f") % (minArmLimits.at(i)+joint_spacer));
        }
        boost::replace_all(minLim,",",".");
        if (i == minArmLimits.size()-1){
            stream << to_string(i+1)+string(" ")+minLim+string(";\n");
        }else{
            stream << to_string(i+1)+string(" ")+minLim+string("\n");
        }
    }

    stream << string("# Upper Bound \n");
    stream << string("param ulim := \n");

    for (std::size_t i=0; i < maxArmLimits.size(); ++i){
        string maxLim;
        if(HANDS){
            if(!final && (hand_code_right == 3 && ((i == joints_arm) || i == joints_arm +1)))
                maxLim=  boost::str(boost::format("%.8f") % (maxArmLimits.at(i)));
            else if(!final && (hand_code_left == 3 && ((i == ((joints_arm * 2) + joints_hand_right)) || (i == ((joints_arm * 2) + joints_hand_right + 1)))))
                maxLim=  boost::str(boost::format("%.8f") % (maxArmLimits.at(i)));
            else
                maxLim=  boost::str(boost::format("%.8f") % (maxArmLimits.at(i)-joint_spacer));
        }
        else{
            if(!final && hand_code_right == 3 && hand_code_left == 3 &&
                    ((i = (joints_arm)) || (i = (joints_arm + 1)) || (i == ((joints_arm * 2) + joints_hand)) || (i == ((joints_arm * 2) + joints_hand + 1))))
                maxLim=  boost::str(boost::format("%.8f") % (maxArmLimits.at(i)));
            else
                maxLim=  boost::str(boost::format("%.8f") % (maxArmLimits.at(i)-joint_spacer));
        }
        boost::replace_all(maxLim,",",".");

        if (i == maxArmLimits.size()-1){
            stream << to_string(i+1)+string(" ")+maxLim+string(";\n");
        }else{
            stream << to_string(i+1)+string(" ")+maxLim+string("\n");
        }
    }
}

void HUMPlanner::writeArmInitPose(ofstream &stream, int arm_code, std::vector<double> &initArmPosture)
{
    // initial configuration
    std::vector<double> hand_pos; this->getHandPos(arm_code,initArmPosture,hand_pos);
    Matrix3d hand_or; this->getHandOr(arm_code, initArmPosture,hand_or);
    std::vector<double> xh; this->getRotAxis(xh,0,hand_or);
    std::vector<double> yh; this->getRotAxis(yh,1,hand_or);
    std::vector<double> zh; this->getRotAxis(zh,2,hand_or);
    std::vector<double> elbow_pos; this->getElbowPos(arm_code,initArmPosture,elbow_pos);
    Matrix3d elbow_or; this->getElbowOr(arm_code, initArmPosture,elbow_or);
    std::vector<double> xe; this->getRotAxis(xe,0,elbow_or);
    std::vector<double> ye; this->getRotAxis(ye,1,elbow_or);
    std::vector<double> ze; this->getRotAxis(ze,2,elbow_or);
    std::vector<double> wrist_pos; this->getWristPos(arm_code,initArmPosture,wrist_pos);
    Matrix3d wrist_or; this->getWristOr(arm_code, initArmPosture,wrist_or);
    std::vector<double> xw; this->getRotAxis(xw,0,wrist_or);
    std::vector<double> yw; this->getRotAxis(yw,1,wrist_or);
    std::vector<double> zw; this->getRotAxis(zw,2,wrist_or);
    double swivel_init = this->getSwivelAngle(arm_code, initArmPosture);

    stream << string("# INITIAL CONFIGURATION \n");
    stream << string("param thet_init := \n");

    for (std::size_t i=0; i < initArmPosture.size(); ++i){
        string initArmstr =  boost::str(boost::format("%.8f") % (initArmPosture.at(i)));
        boost::replace_all(initArmstr,",",".");
        if (i == initArmPosture.size()-1){
            stream << to_string(i+1)+string(" ")+initArmstr+string(";\n");
        }else{
            stream << to_string(i+1)+string(" ")+initArmstr+string("\n");
        }
    }

    // hand position
    stream << string("param Hand_init := \n");
    string hand_pos_x =  boost::str(boost::format("%.8f") % (hand_pos.at(0))); boost::replace_all(hand_pos_x,",",".");
    stream << to_string(1)+string(" ")+hand_pos_x+string("\n");
    string hand_pos_y =  boost::str(boost::format("%.8f") % (hand_pos.at(1))); boost::replace_all(hand_pos_y,",",".");
    stream << to_string(2)+string(" ")+hand_pos_y+string("\n");
    string hand_pos_z =  boost::str(boost::format("%.8f") % (hand_pos.at(2))); boost::replace_all(hand_pos_z,",",".");
    stream << to_string(3)+string(" ")+hand_pos_z+string(";\n");

    // hand orientation
    stream << string("param x_H_init := \n");
    string hand_or_x0 =  boost::str(boost::format("%.8f") % (xh[0])); boost::replace_all(hand_or_x0,",",".");
    stream << to_string(1)+string(" ")+hand_or_x0+string("\n");
    string hand_or_x1 =  boost::str(boost::format("%.8f") % (xh[1])); boost::replace_all(hand_or_x1,",",".");
    stream << to_string(2)+string(" ")+hand_or_x1+string("\n");
    string hand_or_x2 =  boost::str(boost::format("%.8f") % (xh[2])); boost::replace_all(hand_or_x2,",",".");
    stream << to_string(3)+string(" ")+hand_or_x2+string(";\n");

    stream << string("param y_H_init := \n");
    string hand_or_y0 =  boost::str(boost::format("%.8f") % (yh[0])); boost::replace_all(hand_or_y0,",",".");
    stream << to_string(1)+string(" ")+hand_or_y0+string("\n");
    string hand_or_y1 =  boost::str(boost::format("%.8f") % (yh[1])); boost::replace_all(hand_or_y1,",",".");
    stream << to_string(2)+string(" ")+hand_or_y1+string("\n");
    string hand_or_y2 =  boost::str(boost::format("%.8f") % (yh[2])); boost::replace_all(hand_or_y2,",",".");
    stream << to_string(3)+string(" ")+hand_or_y2+string(";\n");

    stream << string("param z_H_init := \n");
    string hand_or_z0 =  boost::str(boost::format("%.8f") % (zh[0])); boost::replace_all(hand_or_z0,",",".");
    stream << to_string(1)+string(" ")+hand_or_z0+string("\n");
    string hand_or_z1 =  boost::str(boost::format("%.8f") % (zh[1])); boost::replace_all(hand_or_z1,",",".");
    stream << to_string(2)+string(" ")+hand_or_z1+string("\n");
    string hand_or_z2 =  boost::str(boost::format("%.8f") % (zh[2])); boost::replace_all(hand_or_z2,",",".");
    stream << to_string(3)+string(" ")+hand_or_z2+string(";\n");

    // elbow position
    stream << string("param Elbow_init := \n");
    string elbow_pos_x =  boost::str(boost::format("%.8f") % (elbow_pos.at(0))); boost::replace_all(elbow_pos_x,",",".");
    stream << to_string(1)+string(" ")+elbow_pos_x+string("\n");
    string elbow_pos_y =  boost::str(boost::format("%.8f") % (elbow_pos.at(1))); boost::replace_all(elbow_pos_y,",",".");
    stream << to_string(2)+string(" ")+elbow_pos_y+string("\n");
    string elbow_pos_z =  boost::str(boost::format("%.8f") % (elbow_pos.at(2))); boost::replace_all(elbow_pos_z,",",".");
    stream << to_string(3)+string(" ")+elbow_pos_z+string(";\n");

    // elbow orientation
    stream << string("param x_E_init := \n");
    string elbow_or_x0 =  boost::str(boost::format("%.8f") % (xe[0])); boost::replace_all(elbow_or_x0,",",".");
    stream << to_string(1)+string(" ")+elbow_or_x0+string("\n");
    string elbow_or_x1 =  boost::str(boost::format("%.8f") % (xe[1])); boost::replace_all(elbow_or_x1,",",".");
    stream << to_string(2)+string(" ")+elbow_or_x1+string("\n");
    string elbow_or_x2 =  boost::str(boost::format("%.8f") % (xe[2])); boost::replace_all(elbow_or_x2,",",".");
    stream << to_string(3)+string(" ")+elbow_or_x2+string(";\n");

    stream << string("param y_E_init := \n");
    string elbow_or_y0 =  boost::str(boost::format("%.8f") % (ye[0])); boost::replace_all(elbow_or_y0,",",".");
    stream << to_string(1)+string(" ")+elbow_or_y0+string("\n");
    string elbow_or_y1 =  boost::str(boost::format("%.8f") % (ye[1])); boost::replace_all(elbow_or_y1,",",".");
    stream << to_string(2)+string(" ")+elbow_or_y1+string("\n");
    string elbow_or_y2 =  boost::str(boost::format("%.8f") % (ye[2])); boost::replace_all(elbow_or_y2,",",".");
    stream << to_string(3)+string(" ")+elbow_or_y2+string(";\n");

    stream << string("param z_E_init := \n");
    string elbow_or_z0 =  boost::str(boost::format("%.8f") % (ze[0])); boost::replace_all(elbow_or_z0,",",".");
    stream << to_string(1)+string(" ")+elbow_or_z0+string("\n");
    string elbow_or_z1 =  boost::str(boost::format("%.8f") % (ze[1])); boost::replace_all(elbow_or_z1,",",".");
    stream << to_string(2)+string(" ")+elbow_or_z1+string("\n");
    string elbow_or_z2 =  boost::str(boost::format("%.8f") % (ze[2])); boost::replace_all(elbow_or_z2,",",".");
    stream << to_string(3)+string(" ")+elbow_or_z2+string(";\n");

    // wrist position
    stream << string("param Wrist_init := \n");
    string wrist_pos_x =  boost::str(boost::format("%.8f") % (wrist_pos.at(0))); boost::replace_all(wrist_pos_x,",",".");
    stream << to_string(1)+string(" ")+elbow_pos_x+string("\n");
    string wrist_pos_y =  boost::str(boost::format("%.8f") % (wrist_pos.at(1))); boost::replace_all(wrist_pos_y,",",".");
    stream << to_string(2)+string(" ")+wrist_pos_y+string("\n");
    string wrist_pos_z =  boost::str(boost::format("%.8f") % (wrist_pos.at(2))); boost::replace_all(wrist_pos_z,",",".");
    stream << to_string(3)+string(" ")+wrist_pos_z+string(";\n");

    // wrist orientation
    stream << string("param x_W_init := \n");
    string wrist_or_x0 =  boost::str(boost::format("%.8f") % (xw[0])); boost::replace_all(wrist_or_x0,",",".");
    stream << to_string(1)+string(" ")+wrist_or_x0+string("\n");
    string wrist_or_x1 =  boost::str(boost::format("%.8f") % (xw[1])); boost::replace_all(wrist_or_x1,",",".");
    stream << to_string(2)+string(" ")+wrist_or_x1+string("\n");
    string wrist_or_x2 =  boost::str(boost::format("%.8f") % (xw[2])); boost::replace_all(wrist_or_x2,",",".");
    stream << to_string(3)+string(" ")+wrist_or_x2+string(";\n");

    stream << string("param y_W_init := \n");
    string wrist_or_y0 =  boost::str(boost::format("%.8f") % (yw[0])); boost::replace_all(wrist_or_y0,",",".");
    stream << to_string(1)+string(" ")+wrist_or_y0+string("\n");
    string wrist_or_y1 =  boost::str(boost::format("%.8f") % (yw[1])); boost::replace_all(wrist_or_y1,",",".");
    stream << to_string(2)+string(" ")+wrist_or_y1+string("\n");
    string wrist_or_y2 =  boost::str(boost::format("%.8f") % (yw[2])); boost::replace_all(wrist_or_y2,",",".");
    stream << to_string(3)+string(" ")+wrist_or_y2+string(";\n");

    stream << string("param z_W_init := \n");
    string wrist_or_z0 =  boost::str(boost::format("%.8f") % (zw[0])); boost::replace_all(wrist_or_z0,",",".");
    stream << to_string(1)+string(" ")+wrist_or_z0+string("\n");
    string wrist_or_z1 =  boost::str(boost::format("%.8f") % (zw[1])); boost::replace_all(wrist_or_z1,",",".");
    stream << to_string(2)+string(" ")+wrist_or_z1+string("\n");
    string wrist_or_z2 =  boost::str(boost::format("%.8f") % (zw[2])); boost::replace_all(wrist_or_z2,",",".");
    stream << to_string(3)+string(" ")+wrist_or_z2+string(";\n");

    // swivel angle
    stream << string("param swivel_init := ");
    string swivel_init_str =  boost::str(boost::format("%.8f") % (swivel_init)); boost::replace_all(swivel_init_str,",",".");
    stream << swivel_init_str+string(";\n");


}

