void HUMPlanner::writeInfoObjectTarget(ofstream &stream, objectPtr obj)
{
    std::vector<double> position; obj->getPos(position);
    std::vector<double> orientation; obj->getOr(orientation);
    std::vector<double> dimension; obj->getSize(dimension);
    Matrix3d Rot_obj; this->RPY_matrix(orientation,Rot_obj);

    stream << string("# OBJECT OF THE TARGET POSITION+RADIUS+ORIENTATION \n");
    stream << string("param ObjTar : 1 2 3 4 5 6 7 8 9 := \n");

    string objx =  boost::str(boost::format("%.8f") % (position.at(0)));
    boost::replace_all(objx,",",".");
    string objy =  boost::str(boost::format("%.8f") % (position.at(1)));
    boost::replace_all(objy,",",".");
    string objz =  boost::str(boost::format("%.8f") % (position.at(2)));
    boost::replace_all(objz,",",".");
    string objxsize =  boost::str(boost::format("%.8f") % (dimension.at(0)/2));
    boost::replace_all(objxsize,",",".");
    string objysize =  boost::str(boost::format("%.8f") % (dimension.at(1)/2));
    boost::replace_all(objysize,",",".");
    string objzsize =  boost::str(boost::format("%.8f") % (dimension.at(2)/2));
    boost::replace_all(objzsize,",",".");
    string objroll =  boost::str(boost::format("%.8f") % (orientation.at(0)));
    boost::replace_all(objroll,",",".");
    string objpitch =  boost::str(boost::format("%.8f") % (orientation.at(1)));
    boost::replace_all(objpitch,",",".");
    string objyaw =  boost::str(boost::format("%.8f") % (orientation.at(2)));
    boost::replace_all(objyaw,",",".");

    stream << to_string(1)+string(" ")+
                       objx+string(" ")+
                       objy+string(" ")+
                       objz+string(" ")+
                       objxsize+string(" ")+
                       objysize+string(" ")+
                       objzsize+string(" ")+
                       objroll+string(" ")+
                       objpitch+string(" ")+
                       objyaw+string(" ")+
                       string(" #")+obj->getName()+
                       string("\n");
    stream << string("  ;\n");

    stream << string(" param n_ObjTar := ")+to_string(1)+string(";\n");

    string Rot_obj_00 = boost::str(boost::format("%.8f") % (Rot_obj(0,0))); boost::replace_all(Rot_obj_00, ",", ".");
    string Rot_obj_01 = boost::str(boost::format("%.8f") % (Rot_obj(0,1))); boost::replace_all(Rot_obj_01, ",", ".");
    string Rot_obj_02 = boost::str(boost::format("%.8f") % (Rot_obj(0,2))); boost::replace_all(Rot_obj_02, ",", ".");
    string Rot_obj_10 = boost::str(boost::format("%.8f") % (Rot_obj(1,0))); boost::replace_all(Rot_obj_10, ",", ".");
    string Rot_obj_11 = boost::str(boost::format("%.8f") % (Rot_obj(1,1))); boost::replace_all(Rot_obj_11, ",", ".");
    string Rot_obj_12 = boost::str(boost::format("%.8f") % (Rot_obj(1,2))); boost::replace_all(Rot_obj_12, ",", ".");
    string Rot_obj_20 = boost::str(boost::format("%.8f") % (Rot_obj(2,0))); boost::replace_all(Rot_obj_20, ",", ".");
    string Rot_obj_21 = boost::str(boost::format("%.8f") % (Rot_obj(2,1))); boost::replace_all(Rot_obj_21, ",", ".");
    string Rot_obj_22 = boost::str(boost::format("%.8f") % (Rot_obj(2,2))); boost::replace_all(Rot_obj_22, ",", ".");

    stream << string("param Rot_obj : 1 2 3 :=  \n");
    stream << string("1 ") + Rot_obj_00 + string(" ") + Rot_obj_01 + string(" ") + Rot_obj_02 + string(" \n");
    stream << string("2 ") + Rot_obj_10 + string(" ") + Rot_obj_11 + string(" ") + Rot_obj_12 + string(" \n");
    stream << string("3 ") + Rot_obj_20 + string(" ") + Rot_obj_21 + string(" ") + Rot_obj_22 + string(" \n");
    stream << string("; \n");
}

void HUMPlanner::writeInfoObjectTargetPlaceRetreat(ofstream &stream,std::vector<double> tar, Matrix4d T_tar_to_obj,std::vector<double> dim, std::string name)
{
    string objx; string objy; string objz;
    string objroll; string objpitch; string objyaw;
    string objxsize; string objysize; string objzsize;
    Matrix4d T_tar; Matrix3d Rot_tar;
    std::vector<double> rpy = {tar.at(3),tar.at(4),tar.at(5)};
    this->RPY_matrix(rpy,Rot_tar);
    T_tar(0,0) = Rot_tar(0,0); T_tar(0,1) = Rot_tar(0,1); T_tar(0,2) = Rot_tar(0,2); T_tar(0,3) = tar.at(0);
    T_tar(1,0) = Rot_tar(1,0); T_tar(1,1) = Rot_tar(1,1); T_tar(1,2) = Rot_tar(1,2); T_tar(1,3) = tar.at(1);
    T_tar(2,0) = Rot_tar(2,0); T_tar(2,1) = Rot_tar(2,1); T_tar(2,2) = Rot_tar(2,2); T_tar(2,3) = tar.at(2);
    T_tar(3,0) = 0; T_tar(3,1) = 0; T_tar(3,2) = 0; T_tar(3,3) = 1;
    Matrix4d T_obj = T_tar * T_tar_to_obj;
    Matrix3d Rot_obj = T_obj.block<3,3>(0,0);
    //Matrix3d Rot_tar_to_obj = T_tar_to_obj.block<3,3>(0,0);
    //Vector3d tar_to_obj = T_tar_to_obj.block<3,1>(0,3);
    std::vector<double> rpy_obj; this->getRPY(rpy_obj,Rot_obj);
    std::vector<double> pos_obj = {T_obj(0,3),T_obj(1,3),T_obj(2,3)};

    stream << string("# OBJECT OF THE TARGET POSITION+RADIUS+ORIENTATION \n");
    stream << string("param ObjTar : 1 2 3 4 5 6 7 8 9 := \n");
    objx =  boost::str(boost::format("%.8f") % (pos_obj.at(0)));
    boost::replace_all(objx,",",".");
    objy =  boost::str(boost::format("%.8f") % (pos_obj.at(1)));
    boost::replace_all(objy,",",".");
    objz =  boost::str(boost::format("%.8f") % (pos_obj.at(2)));
    boost::replace_all(objz,",",".");
    objxsize =  boost::str(boost::format("%.8f") % (dim.at(0)/2));
    boost::replace_all(objxsize,",",".");
    objysize =  boost::str(boost::format("%.8f") % (dim.at(1)/2));
    boost::replace_all(objysize,",",".");
    objzsize =  boost::str(boost::format("%.8f") % (dim.at(2)/2));
    boost::replace_all(objzsize,",",".");
    objroll =  boost::str(boost::format("%.8f") % (rpy_obj.at(0)));
    boost::replace_all(objroll,",",".");
    objpitch =  boost::str(boost::format("%.8f") % (rpy_obj.at(1)));
    boost::replace_all(objpitch,",",".");
    objyaw =  boost::str(boost::format("%.8f") % (rpy_obj.at(2)));
    boost::replace_all(objyaw,",",".");
    stream << to_string(1)+string(" ")+
                       objx+string(" ")+
                       objy+string(" ")+
                       objz+string(" ")+
                       objxsize+string(" ")+
                       objysize+string(" ")+
                       objzsize+string(" ")+
                       objroll+string(" ")+
                       objpitch+string(" ")+
                       objyaw+string(" ")+
                       string(" #")+name+
                       string("\n");
    stream << string(";\n");
    stream << string("param n_ObjTar := ")+to_string(1)+string(";\n");

    string Rot_obj_00 = boost::str(boost::format("%.8f") % (Rot_obj(0,0))); boost::replace_all(Rot_obj_00, ",", ".");
    string Rot_obj_01 = boost::str(boost::format("%.8f") % (Rot_obj(0,1))); boost::replace_all(Rot_obj_01, ",", ".");
    string Rot_obj_02 = boost::str(boost::format("%.8f") % (Rot_obj(0,2))); boost::replace_all(Rot_obj_02, ",", ".");
    string Rot_obj_10 = boost::str(boost::format("%.8f") % (Rot_obj(1,0))); boost::replace_all(Rot_obj_10, ",", ".");
    string Rot_obj_11 = boost::str(boost::format("%.8f") % (Rot_obj(1,1))); boost::replace_all(Rot_obj_11, ",", ".");
    string Rot_obj_12 = boost::str(boost::format("%.8f") % (Rot_obj(1,2))); boost::replace_all(Rot_obj_12, ",", ".");
    string Rot_obj_20 = boost::str(boost::format("%.8f") % (Rot_obj(2,0))); boost::replace_all(Rot_obj_20, ",", ".");
    string Rot_obj_21 = boost::str(boost::format("%.8f") % (Rot_obj(2,1))); boost::replace_all(Rot_obj_21, ",", ".");
    string Rot_obj_22 = boost::str(boost::format("%.8f") % (Rot_obj(2,2))); boost::replace_all(Rot_obj_22, ",", ".");

    stream << string("param Rot_obj : 1 2 3 :=  \n");
    stream << string("1 ") + Rot_obj_00 + string(" ") + Rot_obj_01 + string(" ") + Rot_obj_02 + string(" \n");
    stream << string("2 ") + Rot_obj_10 + string(" ") + Rot_obj_11 + string(" ") + Rot_obj_12 + string(" \n");
    stream << string("3 ") + Rot_obj_20 + string(" ") + Rot_obj_21 + string(" ") + Rot_obj_22 + string(" \n");
    stream << string("; \n");
}

