    string Rot_tar_obj_right_22 = boost::str(boost::format("%.8f") % (Rot_tar_to_obj_right(2, 2))); boost::replace_all(Rot_tar_obj_right_22, ",", ".");

    stream << string("param Rot_tar_obj_right : 1 2 3 :=  \n");
    stream << string("1 ")+Rot_tar_obj_right_00+string(" ")+Rot_tar_obj_right_01+string(" ")+Rot_tar_obj_right_02+string(" \n");
    stream << string("2 ")+Rot_tar_obj_right_10+string(" ")+Rot_tar_obj_right_11+string(" ")+Rot_tar_obj_right_12+string(" \n");
    stream << string("3 ")+Rot_tar_obj_right_20+string(" ")+Rot_tar_obj_right_21+string(" ")+Rot_tar_obj_right_22+string(" \n");
    stream << string("; \n");

    string tar_to_obj_right_0 = boost::str(boost::format("%.8f") % (tar_to_obj_right(0))); boost::replace_all(tar_to_obj_right_0, ",", ".");
