                        stream << string(" else if (i1 = 1 && i2 = 2) then -sin(theta_") + name_finger + string("_left[") + to_string(j+1) + string("]) \n");
                        stream << string(" else if (i1 = 1 && i2 = 3) then 0 \n");
                        stream << string(" else if (i1 = 1 && i2 = 4) then a_") + name_finger + string("_left[") + to_string(j+1) + string("] \n");

                        stream << string("# Second Row \n");
