                        stream << string(" else if (i1 = 2 && i2 = 2) then cos(theta_") + name_finger + string("_left[") + to_string(j+1) + string("]) * cos(alpha_") + name_finger + string("_left[") + to_string(j+1) + string("]) \n");
                        stream << string(" else if (i1 = 2 && i2 = 3) then -sin(alpha_") + name_finger + string("_left[") + to_string(j+1) + string("]) \n");
