                        stream << string(" else if (i1 = 4 && i2 = 2) then 0 \n");
                        stream << string(" else if (i1 = 4 && i2 = 3) then 0 \n");
                        stream << string(" else if (i1 = 4 && i2 = 4) then 1 \n");
                        stream << string("; \n");
