                    stream << string("var ") + name_finger + string("_1b_left   {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_1a_left[i1,j] * TF_") + name_finger + string("_1_2_left[j,i2]; \n");
                    stream << string("var ") + name_finger + string("_2r_left   {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_1b_left[i1,j] * TF_") + name_finger + string("_2_3_left[j,i2]; \n");
                    stream << string("var ") + name_finger + string("_2v_left   {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_2r_left[i1,j] * TF_") + name_finger + string("_3_4_left[j,i2]; \n");
                    stream << string("var ") + name_finger + string("_3r_left   {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_2v_left[i1,j] * TF_") + name_finger + string("_4_5_left[j,i2]; \n");
                    stream << string("var ") + name_finger + string("_3v_left   {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_3r_left[i1,j] * TF_") + name_finger + string("_5_6_left[j,i2]; \n");
                    stream << string("var ") + name_finger + string("_4r_left   {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_3v_left[i1,j] * TF_") + name_finger + string("_6_7_left[j,i2]; \n");
                    stream << string("var ") + name_finger + string("_4v_left   {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_4r_left[i1,j] * TF_") + name_finger + string("_7_8_left[j,i2]; \n");
                    stream << string("var ") + name_finger + string("_tip_left  {i1 in 1..4, i2 in 1..4} = sum {j in 1..4}  ") + name_finger + string("_4v_left[i1,j] * TF_") + name_finger + string("_8_9_left[j,i2]; \n");

                    string tolHand1 =  boost::str(boost::format("%.8f") % tolsHand(i,0)); boost::replace_all(tolHand1,",",".");
                    string tolHand2 =  boost::str(boost::format("%.8f") % tolsHand(i,1)); boost::replace_all(tolHand2,",",".");
                    string tolHand3 =  boost::str(boost::format("%.8f") % tolsHand(i,2)); boost::replace_all(tolHand3,",",".");
