           string tyy2_0 = boost::str(boost::format("%.8f") % tols_0(1,1)); boost::replace_all(tyy2_0,",",".");
           string tyy2_1 = boost::str(boost::format("%.8f") % tols_1(1,1)); boost::replace_all(tyy2_1,",",".");
