                PostureMod << string("subject to Arm_Hand{i1 in 4..9, i2 in 1..3,l in 1..") + threshold_iterations_right + string("}:  \n");
                PostureMod << string("(Points_Arm_left[i1,1,l] - Points_Hand_right[i2,1,l])^2 + \n");
