                PostureMod << string("(Points_Arm_left[i1,1,l] - Points_Hand_right[i2,1,l])^2 + \n");
                PostureMod << string("(Points_Arm_left[i1,2,l] - Points_Hand_right[i2,2,l])^2 + \n");
                PostureMod << string("(Points_Arm_left[i1,3,l] - Points_Hand_right[i2,3,l])^2 - \n");
                PostureMod << string("(Points_Arm_left[i1,4,l] + Points_Hand_right[i2,4,l])^2 >= 0; \n");
